B.aN4=s(["Pongo mermelada en el pan.","Em ph\u1ebft m\u1ee9t l\xean b\xe1nh m\xec."],t.s)
B.bKk=s(["El pastel est\xe1 calentito.","B\xe1nh n\u01b0\u1edbng c\xf2n \u1ea5m."],t.s)
B.c_H=s(["Me gusta el jam\xf3n.","Em th\xedch gi\u0103m b\xf4ng."],t.s)
